import React, { useState } from 'react';
import axios from 'axios';
import { jsPDF } from 'jspdf';

// Material UI imports
import {
  Container,
  Paper,
  Typography,
  Button,
  Box,
  CircularProgress,
  Alert,
  TextField,
} from '@mui/material';
import { CloudUpload } from '@mui/icons-material';

function App() {
  const [selectedFile, setSelectedFile] = useState(null);
  const [analysisResult, setAnalysisResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState('');

  // Handle file input changes
  const handleFileChange = (e) => {
    setSelectedFile(e.target.files[0]);
    setAnalysisResult(null);
    setErrorMsg('');
  };

  // Handle form submission to send file to backend
  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedFile) {
      setErrorMsg('Please select a file before analyzing.');
      return;
    }
    setLoading(true);
    setErrorMsg('');
    setAnalysisResult(null);

    const formData = new FormData();
    formData.append('file', selectedFile);

    try {
      const response = await axios.post('http://127.0.0.1:8000/analyze', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      });
      setAnalysisResult(response.data);
    } catch (error) {
      console.error('Error in Axios request:', error);
      const msg =
        error.response?.data?.detail || 'Error analyzing file. Please try again.';
      setErrorMsg(msg);
    }
    setLoading(false);
  };

  // Download the analysis report as a PDF
  const downloadPDFReport = () => {
    const doc = new jsPDF();
    doc.setFontSize(16);
    doc.text('Malware Analysis Report', 10, 20);
    doc.setFontSize(12);
    doc.text(`Filename: ${analysisResult.filename}`, 10, 30);
    doc.text(`Risk Factor: ${analysisResult.risk_factor}/100`, 10, 40);
    doc.text('YARA Analysis:', 10, 50);
    doc.text(`${analysisResult.risk_details?.yara || 'N/A'}`, 10, 60);
    if (analysisResult.pe_info) {
      if (analysisResult.pe_info.error) {
        doc.text(`PE Analysis Error: ${analysisResult.pe_info.error}`, 10, 70);
      } else {
        doc.text(`Sections: ${analysisResult.pe_info.sections.join(', ')}`, 10, 70);
        doc.text(`Imports: ${analysisResult.pe_info.imports.join(', ')}`, 10, 80);
      }
    }
    doc.text('Detailed Risk Breakdown:', 10, 90);
    doc.text(`Sections Risk: ${analysisResult.risk_details?.sections_risk || 0}`, 10, 100);
    doc.text(`Import Risk: ${analysisResult.risk_details?.import_risk || 0}`, 10, 110);
    doc.save('analysis_report.pdf');
  };

  return (
    <Container maxWidth="md" sx={{ mt: 4 }}>
      <Paper elevation={3} sx={{ p: 4 }}>
        <Typography variant="h4" align="center" gutterBottom>
          Malware Detection Web App
        </Typography>

        <Box
          component="form"
          onSubmit={handleSubmit}
          sx={{
            display: 'flex',
            flexDirection: 'column',
            gap: 2,
            mt: 2,
          }}
        >
          {/* Button to choose file */}
          <Button
            variant="contained"
            component="label"
            startIcon={<CloudUpload />}
            color="primary"
          >
            Choose File
            <input
              type="file"
              hidden
              accept=".exe"
              onChange={handleFileChange}
            />
          </Button>

          {/* Display selected file name if any */}
          {selectedFile && (
            <TextField
              label="Selected File"
              variant="outlined"
              fullWidth
              value={selectedFile.name}
              InputProps={{
                readOnly: true,
              }}
            />
          )}

          {/* Submit / Analyze button */}
          <Button variant="contained" color="secondary" type="submit" disabled={loading}>
            {loading ? <CircularProgress size={24} /> : 'Analyze File'}
          </Button>
        </Box>

        {/* Display error message */}
        {errorMsg && (
          <Alert severity="error" sx={{ mt: 2 }}>
            {errorMsg}
          </Alert>
        )}

        {/* Display formatted analysis report */}
        {analysisResult && (
          <Box sx={{ mt: 4 }}>
            <Typography variant="h5" gutterBottom>
              Analysis Report
            </Typography>
            <Paper elevation={1} sx={{ p: 2, backgroundColor: '#f5f5f5' }}>
              <Typography variant="subtitle1" color="textSecondary">
                Filename: {analysisResult.filename}
              </Typography>
              <Typography variant="h6" sx={{ mt: 1 }}>
                Risk Factor: {analysisResult.risk_factor}/100
              </Typography>

              <Box sx={{ mt: 2 }}>
                <Typography variant="subtitle2">YARA Analysis:</Typography>
                <Typography variant="body2">
                  {analysisResult.risk_details?.yara || 'No YARA result.'}
                </Typography>
              </Box>

              {analysisResult.pe_info && (
                <Box sx={{ mt: 2 }}>
                  {analysisResult.pe_info.error ? (
                    <Typography variant="body2" color="error">
                      PE Analysis Error: {analysisResult.pe_info.error}
                    </Typography>
                  ) : (
                    <>
                      <Typography variant="subtitle2">PE Analysis:</Typography>
                      <Typography variant="body2">
                        Sections: {analysisResult.pe_info.sections.join(', ') || 'N/A'}
                      </Typography>
                      <Typography variant="body2">
                        Imports: {analysisResult.pe_info.imports.join(', ') || 'N/A'}
                      </Typography>
                    </>
                  )}
                </Box>
              )}

              <Box sx={{ mt: 2 }}>
                <Typography variant="subtitle2">Detailed Risk Breakdown:</Typography>
                <Typography variant="body2">
                  Sections Risk: {analysisResult.risk_details?.sections_risk || 0}
                </Typography>
                <Typography variant="body2">
                  Import Risk: {analysisResult.risk_details?.import_risk || 0}
                </Typography>
              </Box>
            </Paper>
            <Box sx={{ mt: 2 }}>
              <Button variant="outlined" onClick={downloadPDFReport}>
                Download PDF Report
              </Button>
            </Box>
          </Box>
        )}
      </Paper>
    </Container>
  );
}

export default App;
